import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../api/axios';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await API.post('/auth/login', { email, password });
      localStorage.setItem('token', res.data.token);
      localStorage.setItem('role', res.data.user.role);
      localStorage.setItem('name', res.data.user.name);
      localStorage.setItem('user_id', res.data.user.id);

      if (res.data.user.role === 'teacher' || res.data.user.role === 'admin') {
        navigate('/dashboard');
      } else {
        navigate('/scan');
      }
    } catch (err) {
      setError('Invalid email or password');
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.left}>
        <div style={styles.brandBox}>
          <h1 style={styles.brandTitle}>QRoll</h1>
          <p style={styles.brandSub}>Smart Attendance System</p>
          <div style={styles.featureList}>
            <div style={styles.featureItem}>✅ Generate QR codes instantly</div>
            <div style={styles.featureItem}>📱 Students scan from any phone</div>
            <div style={styles.featureItem}>📊 Auto attendance reports</div>
            <div style={styles.featureItem}>🔒 Secure JWT authentication</div>
          </div>
        </div>
      </div>

      <div style={styles.right}>
        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle}>Welcome Back</h2>
            <p style={styles.cardSub}>Sign in to your account</p>
          </div>

          {error && (
            <div style={styles.errorBox}>
              ⚠️ {error}
            </div>
          )}

          <form onSubmit={handleLogin}>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Email Address</label>
              <input
                style={styles.input}
                type="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>

            <div style={styles.inputGroup}>
              <label style={styles.label}>Password</label>
              <input
                style={styles.input}
                type="password"
                placeholder="Enter your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>

            <button style={styles.button} type="submit">
              Login →
            </button>
          </form>

          <div style={styles.divider}>
            <span style={styles.dividerText}>New to QRoll?</span>
          </div>

          <button
            style={styles.registerBtn}
            onClick={() => navigate('/register')}
          >
            Create Student Account
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: 'flex',
    height: '100vh',
    fontFamily: "'Segoe UI', sans-serif",
  },
  left: {
    flex: 1,
    background: 'linear-gradient(135deg, #1F3864 0%, #2E75B6 60%, #3498db 100%)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '40px',
  },
  brandBox: {
    color: '#fff',
    maxWidth: '380px',
  },
  brandTitle: {
    fontSize: '56px',
    fontWeight: '800',
    color: '#fff',
    margin: '0 0 8px 0',
    letterSpacing: '-1px',
  },
  brandSub: {
    fontSize: '18px',
    color: 'rgba(255,255,255,0.8)',
    marginBottom: '48px',
  },
  featureList: {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
  },
  featureItem: {
    fontSize: '15px',
    color: 'rgba(255,255,255,0.9)',
    backgroundColor: 'rgba(255,255,255,0.1)',
    padding: '12px 18px',
    borderRadius: '10px',
    borderLeft: '3px solid rgba(255,255,255,0.5)',
  },
  right: {
    flex: 1,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#f5f7fa',
    padding: '40px',
  },
  card: {
    backgroundColor: '#fff',
    padding: '48px 40px',
    borderRadius: '16px',
    boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
    width: '100%',
    maxWidth: '420px',
  },
  cardHeader: {
    marginBottom: '32px',
  },
  cardTitle: {
    fontSize: '28px',
    fontWeight: '700',
    color: '#1F3864',
    margin: '0 0 6px 0',
  },
  cardSub: {
    color: '#888',
    fontSize: '14px',
    margin: 0,
  },
  errorBox: {
    backgroundColor: '#fff5f5',
    border: '1px solid #feb2b2',
    color: '#c0392b',
    padding: '12px 16px',
    borderRadius: '8px',
    marginBottom: '20px',
    fontSize: '14px',
  },
  inputGroup: {
    marginBottom: '20px',
  },
  label: {
    display: 'block',
    fontSize: '13px',
    fontWeight: '600',
    color: '#444',
    marginBottom: '6px',
  },
  input: {
    width: '100%',
    padding: '12px 16px',
    borderRadius: '8px',
    border: '1.5px solid #e2e8f0',
    fontSize: '14px',
    boxSizing: 'border-box',
    outline: 'none',
    transition: 'border 0.2s',
    color: '#333',
  },
  button: {
    width: '100%',
    padding: '14px',
    backgroundColor: '#2E75B6',
    color: '#fff',
    border: 'none',
    borderRadius: '8px',
    fontSize: '16px',
    fontWeight: '600',
    cursor: 'pointer',
    marginTop: '8px',
    letterSpacing: '0.3px',
  },
  divider: {
    textAlign: 'center',
    margin: '24px 0',
    borderTop: '1px solid #eee',
    paddingTop: '24px',
  },
  dividerText: {
    color: '#888',
    fontSize: '13px',
  },
  registerBtn: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#fff',
    color: '#2E75B6',
    border: '2px solid #2E75B6',
    borderRadius: '8px',
    fontSize: '15px',
    fontWeight: '600',
    cursor: 'pointer',
  },
};

export default Login;
